"""Generate docs/detection-rules.md from rule metadata so documentation cannot drift from code."""

from __future__ import annotations

from regexsoc.rules.definitions import Rule


def render_markdown(rules: list[Rule]) -> str:
    out = [
        "# Detection Rules\n",
        "_Generated by `python -m regexsoc rules docs`. Do not edit by hand._\n",
        "Severity is derived from the risk score using the configurable bands "
        "(0-29 LOW, 30-59 MEDIUM, 60-79 HIGH, 80-100 CRITICAL). Risk scores are a triage aid, "
        "not a probability of compromise.\n",
    ]
    for r in rules:
        patterns = "\n".join(f"```regex\n{p}\n```" for p in r.patterns)
        how = {
            "correlation": "Correlation: the pattern(s) select candidate events; window logic is in the parameters.",
            "ioc": "IOC extraction: matches are recorded as indicators, no alert on their own.",
            "watchlist": "Fires when an extracted IOC is on the analyst-supplied watchlist.",
        }.get(r.target, f"Event rule matched against: `{r.target}`.")
        params = f"\n**Parameters:** `{r.params}`\n" if r.params else ""
        out.append(
            f"\n## {r.id}: {r.name}\n\n"
            f"- **Category:** {r.category}\n- **Severity:** {r.severity}\n"
            f"- **Risk contribution:** +{r.risk_score}\n- **Default state:** "
            f"{'enabled' if r.enabled else 'disabled'}\n- **How it works:** {how}\n\n"
            f"**What it detects:** {r.description}\n\n**Why it matters:** {r.why}\n\n"
            f"**Example log:** `{r.example}`\n\n**Regex pattern(s):**\n\n{patterns}\n{params}\n"
            f"**Possible false positives:** {r.false_positives}\n\n"
            f"**Recommended analyst action:** {r.recommended_response}\n"
        )
    return "".join(out)
